            public boolean validateWrite()
    {
        boolean ret = super();

        ret = ret && this.validateName() && this.validateSourceLevel();

        return ret;
    }

    private boolean validateName()
    {
        if (strFind(this.Name, '-', 1, strLen(this.Name)))
        {
            return checkFailed("@GlobalUnifiedPricing:GUPAttributeGroupNameContainsReservedCharacterError");
        }

        if (this.Name == "@GlobalUnifiedPricing:GUPPriceAttributeGroupSelectionAll")
        {
            return checkFailed(strFmt("@GlobalUnifiedPricing:GUPAttributeGroupNameContainsReservedWordAllError", "@GlobalUnifiedPricing:GUPPriceAttributeGroupSelectionAll"));
        }

        return true;
    }

    private boolean validateSourceLevel()
    {
        if (this.SourceLevel != GUPPricingAttributeSourceLevel::Header && this.SourceLevel != GUPPricingAttributeSourceLevel::Line )
        {
            return checkFailed("@GlobalUnifiedPricing:GUPPricingAttributeGroupLevelSourceLevelWarning");
        }

        return true;
    }

    public boolean validateStructure()
    {
        GUPPricingAttributeGroup pricingAttributeGroup;
        GUPPricingAttributeLink pricingAttributeLink;
        Set unionSet;
        boolean isValid = true;
        Set recordSet = this.getAttributeLinkRecordSet();
        int numberOfLink = recordSet.elements();
        SetEnumerator setEnum = recordSet.getEnumerator();
        Set allNestedAttributeClassIdSet = new Set(Types::Int64);
        Set allAttributeClassIdSet = new Set(Types::Int64);

        if (recordSet.empty())
        {
            warning("@GlobalUnifiedPricing:GUPPricingAttributeGroup_EmptyPricingAttributeGroup");
            isValid = false;
        }
        else
        {
            while (setEnum.moveNext())
            {
                pricingAttributeLink = setEnum.current();
                if (pricingAttributeLink.Source != GUPPricingAttributeSource::CustomerPriceGroup
                    && pricingAttributeLink.Source != GUPPricingAttributeSource::ProductPriceGroup)
                {
                    allAttributeClassIdSet.add(pricingAttributeLink.PriceAttributeClassId);
                }
                else
                {
                    this.addAllNestedAttributeClassIdFromCustomerOrProductPriceGroup(allNestedAttributeClassIdSet, pricingAttributeLink.Source);
                }
            }
            unionSet = Set::intersection(allAttributeClassIdSet, allNestedAttributeClassIdSet);
            if (!unionSet.empty())
            {
                SetEnumerator unionSetEnum = unionSet.getEnumerator();
                while (unionSetEnum.moveNext())
                {
                    GUPPricingAttributeLink attributeLink;
                    select firstonly AttributeName from attributeLink where attributeLink.PriceAttributeClassId == unionSetEnum.current();
                    warning(strFmt("@GlobalUnifiedPricing:GUPPricingAttributeExistingInGroupError", attributeLink.AttributeName));
                }
                return false;
            }

            setEnum.reset();
            setEnum.moveNext();
            pricingAttributeLink = setEnum.current();
            unionSet = pricingAttributeLink.getAttributeGroupRecIdRecordSet();
          
            while (setEnum.moveNext())
            {
                pricingAttributeLink = setEnum.current();
                unionSet = Set::intersection(unionSet, pricingAttributeLink.getAttributeGroupRecIdRecordSet());
            }

            unionSet.remove(this.RecId);

            if (!unionSet.empty())
            {
                setEnum = unionSet.getEnumerator();

                while (setEnum.moveNext())
                {
                    pricingAttributeGroup = GUPPricingAttributeGroup::find(setEnum.current());

                    if (pricingAttributeGroup.getAttributeLinkRecordSet().elements() == numberOfLink)
                    {
                        warning(strFmt("@GlobalUnifiedPricing:GUPPricingAttributeGroup_DuplicateStructure", pricingAttributeGroup.Name));
                        isValid = false;
                        break;
                    }
                }
            }
        }

        return isValid;
    }

    private Set getAttributeLinkRecordSet()
    {
        GUPPricingAttributeLink pricingAttributeLink;
        Set recordSet = new Set(Types::Record);

        while select PriceAttributeClassId, AttributeProviderClassId, AttributeName, TypeName, DefaultValue, Source from pricingAttributeLink where pricingAttributeLink.PriceAttributeGroup == this.RecId
        {
            recordSet.add(pricingAttributeLink);
        }

        return recordSet;
    }

    public static GUPPricingAttributeGroup find(RecId _recId, boolean _update = false)
    {
        GUPPricingAttributeGroup  pricingAttributeGroup;

        pricingAttributeGroup.selectForUpdate(_update);

        if (_recId)
        {
            select firstonly pricingAttributeGroup
                where pricingAttributeGroup.RecId == _recId;
        }

        return pricingAttributeGroup;
    }

    public static GUPPricingAttributeGroup findByName(Name _name, boolean _update = false)
    {
        GUPPricingAttributeGroup  pricingAttributeGroup;

        pricingAttributeGroup.selectForUpdate(_update);

        select firstonly pricingAttributeGroup
            where pricingAttributeGroup.Name == _name;

        return pricingAttributeGroup;
    }

    internal boolean matchSource(GUPPricingAttributeSource _source)
    {
        GUPPricingAttributeLink link;

        while select link where link.PriceAttributeGroup == this.RecId
        {
            if (GUPPricingAttributeRepository::getPricingAttributeAttributeAsObject(
                link.pricingAttribute(),
                attributeStr(GUPPricingAttributeSourceDiscoveryAttribute)).parmSource() != _source)
            {
                return false;
            }
        }

        return true;
    }

    public static boolean isPricingAttributeGroupUsed(RecId _recId)
    {
        boolean ret = false;

        if (_recId)
        {
            GUPPricingRule  gupPricingRule;

            select firstonly RecId from gupPricingRule
                where gupPricingRule.PriceAttributeGroup == _recId;

            ret = gupPricingRule.recid;

            if (!ret)
            {
                GUPPricingAttributeLink attributeLink;
                GUPPricingRuleCondition ruleCondition;
                GUPPricingAttributeGroup upsCustomerOrProductPriceGroup;

                select firstonly RecId from  attributeLink
                    where attributeLink.PriceAttributeClassId == classNum(GUPPricingAttributeCustomerPriceGroup)
                        || attributeLink.PriceAttributeClassId == classNum(GUPPricingAttributeProductPriceGroup)
                join RecId from ruleCondition
                    where ruleCondition.ConditionAttribute == attributeLink.RecId
                join RecId from upsCustomerOrProductPriceGroup
                    where (upsCustomerOrProductPriceGroup.GroupType == GUPPricingAttributeGroupType::Customer
                            || upsCustomerOrProductPriceGroup.GroupType == GUPPricingAttributeGroupType::Product)
                        && upsCustomerOrProductPriceGroup.Name == RuleCondition.ConditionValue
                        && upsCustomerOrProductPriceGroup.RecId == _recId;

                ret = attributeLink.recid;
            }
        }

        return ret;
    }

/// <summary>
/// Include or exclude line related to current pricing rule
/// </summary>
/// <param name = "_lineType">Action to perform - include or exclude</param>
/// <param name = "_refTableId">Reference table Id of line to be included/excluded</param>
/// <param name = "_refRecId">Reference record Id of line to be included/excluded</param>
public void inclExclRelLine(GUPPricingAttributeLineType _lineType, RefTableId _refTableId, RefRecId _refRecId)
{
    if (_lineType == GUPPricingAttributeLineType::Exclude)
    {
        GUPPricingAttributeLineState::excludeLine(this.TableId, this.RecId, _refTableId, _refRecId);
    }
    else
    {
        GUPPricingAttributeLineState::includeLine(this.TableId, this.RecId, _refTableId, _refRecId);
    }
}

    private void addAllNestedAttributeClassIdFromCustomerOrProductPriceGroup(Set _allRecordAttributesLinkSet, GUPPricingAttributeSource _attributeSource)
    {
        GUPPricingAttributeGroup pricingAttributeGroup;
        GUPPricingAttributeLink pricingAttributeLink;
        GUPPricingAttributeGroupType groupType = _attributeSource == GUPPricingAttributeSource::CustomerPriceGroup ?
             GUPPricingAttributeGroupType::Customer : GUPPricingAttributeGroupType::Product;

        while select PriceAttributeClassId from pricingAttributeLink join pricingAttributeGroup
            where pricingAttributeLink.PriceAttributeGroup == pricingAttributeGroup.RecId
                && pricingAttributeGroup.GroupType == groupType
                && pricingAttributeGroup.IsValid == NoYes::Yes
        {
            _allRecordAttributesLinkSet.add(pricingAttributeLink.PriceAttributeClassId);
        }
    }

    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(GUPPricingAttributeGroup, Name):
                if (!this.FriendlyName)
                {
                    this.FriendlyName = this.Name;
                }
                break;
        }
    }
